        vm.roll(lockBlock + 2);
        vm.prank(actor);
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "settle must succeed two blocks after locking in a guess");
    }
