pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 x, address actor) public {
        // wide domain: any actor, any preimage x
        vm.assume(actor != address(0));

        // lock in the guess keccak(preimage = x)
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(bytes32(x))));

        // roll far past the target block (+1) so that blockhash(target) == 0;
        // hence the answer is keccak256(abi.encodePacked(bytes32(0))), which is
        // the stored guess h exactly when x == 0.
        vm.roll(block.number + 300);
        vm.prank(actor);
        c.settle();

        // General rule: the caller is paid 2 ether (contract balance drops to 0)
        // exactly when the locked hash matches the answer, i.e. when x == 0;
        // otherwise the contract keeps the 2 ether.
        assertTrue(
            address(c).balance == (x == 0 ? 0 : 2 ether),
            "payout must follow the actually stored guess"
        );
    }
}

