pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }
    function testFuzz_property(address actor, bytes32 guess, uint256 jump) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);
        uint256 target = bound(block.number + 1 + (jump % 100), block.number + 2, type(uint64).max);
        vm.roll(target);
        bool ok1;
        try c.settle() { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1);
        // General rule: once a guess has been settled, it is consumed;
        // a second settle() must revert for ANY caller.
        bool ok2;
        try c.settle() { ok2 = true; } catch { ok2 = false; }
        assertTrue(!ok2);
    }
}

