pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 offset, address actor) public {
        // keep the offset nonzero and hash it so it can never accidentally equal the answer
        offset = bound(offset, 1, type(uint256).max);
        vm.assume(actor != address(0) && actor != address(c));

        // lock in a guess for the next block
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(bytes32(0));

        // compute the answer that settle() will derive and perturb it by a hashed offset,
        // guaranteeing the guess is WRONG for every admissible input
        uint256 targetBlock = block.number + 1;
        vm.roll(targetBlock + 1);
        bytes32 answer = keccak256(abi.encodePacked(blockhash(targetBlock)));
        bytes32 wrongGuess = answer ^ bytes32(keccak256(abi.encode(offset)));

        // install the wrong guess: must be done before lockInGuess's block constraint matters,
        // so instead lock with an arbitrary hash and rely on settle comparing against `answer`.
        // We need the stored guess to be wrongGuess; use a fresh contract instance flow:
        // settle the original guess first (it does not matter if it wins or not, balance captured after).
        uint256 balBefore = address(c).balance;
        try c.settle() {
            // ok
        } catch {
            // if the random first guess somehow won (prize paid), re-setup is unnecessary for rule:
            // the rule below still holds only if no payout occurred; skip by asserting paid-out state
            // is impossible to distinguish here — so guard by asserting the invariant directly.
        }

        // Re-run the decisive scenario deterministically with the wrong guess:
        C c2 = new C{value: 1 ether}();
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c2.lockInGuess{value: 1 ether}(wrongGuess);
        vm.roll(block.number + 2);

        uint256 balBefore2 = address(c2).balance;
        vm.prank(actor);
        c2.settle();
        uint256 balAfter2 = address(c2).balance;

        // General rule: a WRONG guess never pays the 2-ether prize.
        assertTrue(balAfter2 == balBefore2, "wrong guess must not be paid");
    }
}

